-- ============================================================
-- 回滚脚本：删除 Fondia 会员/积分/商城 管理后台菜单
-- 对应初始化脚本：init_fondia_member_menu.sql
-- 执行顺序：先删角色授权，再删菜单权限
-- ============================================================

-- 1) 删除角色-菜单关联
DELETE FROM `sys_role_permission`
WHERE `permission_id` IN (
  -- 会员运营 (090-101)
  '2000100000000000090',
  '2000100000000000091',
  '2000100000000000092',
  '2000100000000000093',
  '2000100000000000094',
  '2000100000000000095',
  '2000100000000000096',
  '2000100000000000097',
  '2000100000000000098',
  '2000100000000000099',
  '2000100000000000100',
  '2000100000000000101',
  -- 积分运营 (110-122)
  '2000100000000000110',
  '2000100000000000111',
  '2000100000000000112',
  '2000100000000000113',
  '2000100000000000114',
  '2000100000000000115',
  '2000100000000000116',
  '2000100000000000117',
  '2000100000000000118',
  '2000100000000000119',
  '2000100000000000120',
  '2000100000000000121',
  '2000100000000000122',
  -- 积分商城 (130-138)
  '2000100000000000130',
  '2000100000000000131',
  '2000100000000000132',
  '2000100000000000133',
  '2000100000000000134',
  '2000100000000000135',
  '2000100000000000136',
  '2000100000000000137',
  '2000100000000000138'
);

-- 2) 删除菜单/按钮权限（子节点与父节点一并删除，顺序无关）
DELETE FROM `sys_permission`
WHERE `id` IN (
  '2000100000000000090',
  '2000100000000000091',
  '2000100000000000092',
  '2000100000000000093',
  '2000100000000000094',
  '2000100000000000095',
  '2000100000000000096',
  '2000100000000000097',
  '2000100000000000098',
  '2000100000000000099',
  '2000100000000000100',
  '2000100000000000101',
  '2000100000000000110',
  '2000100000000000111',
  '2000100000000000112',
  '2000100000000000113',
  '2000100000000000114',
  '2000100000000000115',
  '2000100000000000116',
  '2000100000000000117',
  '2000100000000000118',
  '2000100000000000119',
  '2000100000000000120',
  '2000100000000000121',
  '2000100000000000122',
  '2000100000000000130',
  '2000100000000000131',
